import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"B 树与外存","description":"","frontmatter":{"title":"B 树与外存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/btree-external.md","filePath":"cs/btree-external.md","lastUpdated":1789023840000}'),h={name:"cs/btree-external.md"};function B(_,a,A,m,f,E){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="b-树与外存" tabindex="-1">B 树与外存 <a class="header-anchor" href="#b-树与外存" aria-label="Permalink to &quot;B 树与外存&quot;">​</a></h1><div class="epigraph"><p>一次磁盘 I/O 能搬一整页键，节点就该有成百扇出；平衡多路树把高度收到三次左右。</p><footer>—— 据 Bayer and McCreight, Organization and Maintenance of Large Ordered Indexes, Acta Informatica 1972 整理</footer></div><p><a href="/cs/rbtree-intuition">上一课</a>把内存字典做到对数次指针追逐。每次追逐在<a href="/cs/rbtree-intuition">SRAM 与 DRAM 阵列</a>上可能只是一次 cache 缺失；若节点在磁盘，一次追逐是毫秒级。<a href="/cs/locality-principle">局部性原理</a>说应一次搬一块。<a href="/cs/paging-vm">虚拟内存分页</a>的页正好是这块的单位。本课不重讲红黑着色。缺口是：节点大小对齐页，多键多孩子，仍保持有序与平衡。本课只钉 B 树直觉，不写 B+ 的叶子链表细节（数据库课再收）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二叉高度 \\(\\log_2 n\\) 对 \\(n=10^9\\) 仍约 30 次 I/O，不可接受。缺口不是更快的磁盘调度，而是<strong>阶 \\(t\\)：每个内部节点至少 \\(t-1\\) 个键、至多 \\(2t-1\\)，孩子数多一个</strong>，高度 \\(\\Theta(\\log_t n)\\)。页对齐让一次 I/O 读完一个节点。</p><p>分裂与合并代替旋转：满节点插入则分裂，根可长高，从而整棵树变高均匀。这是 Bayer–McCreight 的维护方式。</p><p><span class="marginnote">B 树的 B 不是 binary。扇出由页大小和键宽决定，常见上百。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点内键有序，孩子 \\(c_i\\) 中的键介于 \\(k_{i-1}\\) 与 \\(k_i\\)。查找：节点内二分或顺序扫（键少则扫），再沿一个孩子下降。插入：降到叶，叶满则分裂，中位键升到父；父满则继续。删除对称地合并或借键。</p>',9)),(e(),s(p,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E4%B8%80%E9%A1%B5%22%5D%20--%3E%20C0%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20ROOT%20--%3E%20C1%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20ROOT%20--%3E%20C2%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20C0%20--%3E%20L%5B%22%E5%8F%B6%E9%A1%B5%EF%BC%9A%E4%BB%8D%E5%AF%B9%E9%BD%90%20I%2FO%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 AVL 相同，平衡是全局高度一致（所有叶同深）。手段从旋转换成分裂合并，因为一次操作应对齐页，而不是改两三个指针。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>I/O 次数 \\(\\Theta(\\log_t n)\\)，通常 \\(\\le 3\\)。这是外存字典的正确合同：代价单位是页，不是 CPU 比较。<a href="/cs/cache-miss-types">cache 缺失分类</a>的强制/容量在页层变成缺页；B 树把工作集收成沿路径的几个节点。</p><p>内存里也可以用 B 树改善 cache 行利用率（B 树缓存友好），但动机最强的是外存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入哈希索引、不把 WAL 写进来。B+ 树把卫星数据只放叶、内部仅作路标，范围扫描更好——数据库课再分。并发锁住节点是又一层。</p><p>后课默认：外存有序索引是 B 树族。内存优先队列不需要全序遍历，可用堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外存代价是页 I/O；高扇出把高度压到个位数。</li><li>满则分裂、根可长高，叶同深。</li><li>只要最小、不要中序遍历时，下一课用堆。</li><li>出处：Bayer and McCreight, <em>Acta Informatica</em>, 1972；Cormen et al. 第 18 章。</li></ul>',9))])}const T=n(h,[["render",B]]);export{b as __pageData,T as default};
